 z$status_group<-ifelse(is.na(z$fu_status),'Missing status',ifelse(z$fu_status %in% deadcodes,'Recorded death',ifelse(z$fu_status==1,'Respondent alive',ifelse(z$fu_status==4,'Nonrespondent alive',ifelse(z$fu_status==10,'Country absent from wave',ifelse(z$fu_status==9,'Unknown vital status','Other status'))))))
