# SMD = (retained mean - comparison mean) / pooled SD, evaluated in each variable's observed subset.
vars<-c(age='Age, years',female='Female',fi_complete='Baseline complete FI',chronic_count='Seven-condition burden',hypertension='Hypertension',diabetes='Diabetes',heart_disease='Heart disease',cancer='Cancer',stroke='Stroke',arthritis='Arthritis',lung_disease='Lung disease',married='Married or partnered',low_education='Low education',poor_srh='Fair or poor self-rated health',adl_any='Any baseline ADL limitation',iadl_any='Any baseline IADL limitation',walk_difficulty='Walking difficulty',fatigue='Fatigue',bmi_continuous='BMI',grip='Grip strength',fi_n_observed='Observed complete-FI items')
binary<-c('female','hypertension','diabetes','heart_disease','cancer','stroke','arthritis','lung_disease','married','low_education','poor_srh','adl_any','iadl_any','walk_difficulty','fatigue')
smd<-function(a,b){a<-a[is.finite(a)];b<-b[is.finite(b)];if(length(a)<2||length(b)<2)return(NA_real_);den<-sqrt((var(a)+var(b))/2);if(den==0)return(if(mean(a)==mean(b))0 else NA_real_);(mean(a)-mean(b))/den}
comparisons<-list();countryrows<-list()
for(coh in cohs){z<-allz[[coh]];comparegroups<-list(All_baseline=rep(TRUE,nrow(z)),Common_score_eligible=z$common,Known_alive_common=z$common&z$known_alive)
 for(cmp in names(comparegroups)){e<-comparegroups[[cmp]];a<-e&z$retained;b<-e&!z$retained
