# Weighted pairwise AUC and weighted mid-distribution rank correlation; no outcome imputation.
w_auc<-function(y,s,w){ok<-is.finite(y)&is.finite(s)&is.finite(w)&w>0;y<-y[ok];s<-s[ok];w<-w[ok];if(length(unique(y))<2)return(NA_real_);o<-order(s);y<-y[o];s<-s[o];w<-w[o];g<-match(s,unique(s));pos<-rowsum(w*(y==1),g,reorder=FALSE)[,1];neg<-rowsum(w*(y==0),g,reorder=FALSE)[,1];sum(pos*(cumsum(neg)-neg/2))/(sum(pos)*sum(neg))}
w_midrank<-function(x,w){o<-order(x);g<-match(x[o],unique(x[o]));wg<-rowsum(w[o],g,reorder=FALSE)[,1];r<-(cumsum(wg)-wg/2)/sum(wg);ans<-numeric(length(x));ans[o]<-r[g];ans}
w_cor<-function(x,y,w){x<-w_midrank(x,w);y<-w_midrank(y,w);mx<-weighted.mean(x,w);my<-weighted.mean(y,w);sum(w*(x-mx)*(y-my))/sqrt(sum(w*(x-mx)^2)*sum(w*(y-my)^2))}
# Default sensitivity specification recorded before the model is run: median covariate imputation with missing indicators; age/FI splines; status-verified alive target; .05-.99 probability clip; 1st-99th percentile weight truncation.
modelvars<-c('age','female','fi_complete','chronic_count','married','low_education','adl_any','iadl_any','walk_difficulty','poor_srh')
ipwstats<-list();ipwdiag<-list();coefrows<-list();balance<-list();targetaudit<-list();B<-200L;set.seed(20261001)
fitweights<-function(q,returnfit=FALSE){r<-as.numeric(is.finite(q$followup_FI));nd<-q;pred<-character()
 for(v in modelvars){miss<-is.na(nd[[v]]);if(all(miss))next;nd[[v]][miss]<-median(nd[[v]],na.rm=TRUE);if(length(unique(nd[[v]]))<2)next;pred<-c(pred,if(v %in% c('age','fi_complete'))paste0('splines::ns(',v,', df=3)') else v);if(any(miss)&&any(!miss)){mn<-paste0(v,'_missing');nd[[mn]]<-as.numeric(miss);pred<-c(pred,mn)}}
 if(length(unique(nd$country))>1){nd$country<-factor(nd$country);pred<-c(pred,'country')};nd$observed<-r;fm<-reformulate(pred,response='observed');fit<-suppressWarnings(glm(fm,data=nd,family=binomial(),control=glm.control(maxit=100)));pr<-as.numeric(predict(fit,type='response'));pc<-pmin(pmax(pr,.05),.99);w0<-mean(r)/pc[r==1];caps<-quantile(w0,c(.01,.99),names=FALSE);wt<-pmin(pmax(w0,caps[1]),caps[2]);ix<-which(r==1);v<-c(FI6_AUROC=w_auc(q$followup_frail[ix],q$FI6[ix],wt),Full_FI_AUROC=w_auc(q$followup_frail[ix],q$fi_complete[ix],wt),FI6_rank_correlation=w_cor(q$FI6[ix],q$followup_FI[ix],wt),Full_FI_rank_correlation=w_cor(q$fi_complete[ix],q$followup_FI[ix],wt));if(returnfit)return(list(v=v,fit=fit,p=pr,clipped=pc,w_raw=w0,w=wt,ix=ix,caps=caps,formula=paste(deparse(fm),collapse=' ')));v}
for(coh in cohs){z<-allz[[coh]];q0<-z[z$common&z$known_alive,];supported_countries<-names(which(tapply(is.finite(q0$followup_FI),q0$country,sum)>0));country_supported<-q0$country %in% supported_countries;q<-q0[country_supported,];obs<-is.finite(q$followup_FI);targetaudit[[coh]]<-data.frame(cohort=coh,common_n=sum(z$common),known_alive_common_n=nrow(q0),country_zero_observation_excluded_n=sum(!country_supported),known_alive_target_n=nrow(q),observed_followup_FI_n=sum(obs),unobserved_followup_FI_n=sum(!obs),recorded_death_excluded_n=sum(z$common&z$status_group=='Recorded death'),unknown_status_excluded_n=sum(z$common&z$status_group %in% c('Unknown vital status','Missing status')),country_wave_absence_excluded_n=sum(z$common&z$status_group=='Country absent from wave'))
 if(sum(obs)<50||sum(!obs)<10){cat('IPW insufficient target',coh,'\n');next};ww<-fitweights(q,TRUE);u<-c(FI6_AUROC=w_auc(q$followup_frail[obs],q$FI6[obs],rep(1,sum(obs))),Full_FI_AUROC=w_auc(q$followup_frail[obs],q$fi_complete[obs],rep(1,sum(obs))),FI6_rank_correlation=cor(q$FI6[obs],q$followup_FI[obs],method='spearman'),Full_FI_rank_correlation=cor(q$fi_complete[obs],q$followup_FI[obs],method='spearman'))
 auditpath<-file.path(out,paste0('IPW_',coh,'_audit.rds'));cached<-if(file.exists(auditpath))readRDS(auditpath) else NULL;cohort_seed<-20261001L+match(coh,cohs);set.seed(cohort_seed);cache_ok<-!is.null(cached)&&!is.null(cached$bootstrap_seed)&&cached$bootstrap_seed==cohort_seed&&identical(q$uid,cached$target$uid)&&isTRUE(all.equal(coef(ww$fit),coef(cached$fit),tolerance=1e-12))&&nrow(cached$bootstrap)==B;boot<-if(cache_ok)cached$bootstrap else matrix(NA_real_,B,4,dimnames=list(NULL,names(u)));if(cache_ok)cat('Verified unchanged model: bootstrap reused',coh,'\n');for(bb in if(cache_ok)integer(0) else seq_len(B)){ix<-sample.int(nrow(q),nrow(q),replace=TRUE);boot[bb,]<-tryCatch(fitweights(q[ix,]),error=function(e)rep(NA_real_,4));if(bb %% 50==0){cat('Bootstrap',coh,bb,'of',B,'\n');flush.console()}}
 for(j in seq_along(u)){vv<-boot[,j];ci<-quantile(vv,c(.025,.975),na.rm=TRUE);ipwstats[[length(ipwstats)+1]]<-data.frame(cohort=coh,metric=names(u)[j],target='Known-alive common-score sample in countries with follow-up observations',target_n=nrow(q),observed_n=sum(obs),unweighted=u[j],IPW=ww$v[j],difference=ww$v[j]-u[j],IPW_CI_low=ci[1],IPW_CI_high=ci[2],bootstrap_success_n=sum(is.finite(vv)),bootstrap_B=B)}
 ipwdiag[[coh]]<-data.frame(cohort=coh,formula=ww$formula,converged=ww$fit$converged,target_n=nrow(q),observed_n=sum(obs),observability_fraction=mean(obs),fitted_probability_min=min(ww$p),fitted_probability_median=median(ww$p),fitted_probability_max=max(ww$p),probability_clip_low=.05,probability_clip_high=.99,clipped_low_n=sum(ww$p<.05),clipped_high_n=sum(ww$p>.99),raw_weight_min=min(ww$w_raw),raw_weight_max=max(ww$w_raw),truncation_low=ww$caps[1],truncation_high=ww$caps[2],truncated_low_n=sum(ww$w_raw<ww$caps[1]),truncated_high_n=sum(ww$w_raw>ww$caps[2]),final_weight_min=min(ww$w),final_weight_max=max(ww$w),effective_sample_size=sum(ww$w)^2/sum(ww$w^2))
 cf<-summary(ww$fit)$coefficients;coefrows[[coh]]<-data.frame(cohort=coh,term=rownames(cf),estimate=cf[,1],SE=cf[,2],z=cf[,3],p=cf[,4],row.names=NULL)
 for(v in modelvars){xx<-q[[v]];ok<-is.finite(xx);xo<-xx[obs];ok2<-is.finite(xo);wm<-weighted.mean(xo[ok2],ww$w[ok2]);mu<-mean(xx[ok]);den<-sd(xx[ok]);balance[[length(balance)+1]]<-data.frame(cohort=coh,variable=v,target_mean=mu,unweighted_observed_mean=mean(xo[ok2]),IPW_observed_mean=wm,target_SD=den,unweighted_standardized_difference=(mean(xo[ok2])-mu)/den,IPW_standardized_difference=(wm-mu)/den)}
 saveRDS(list(target=q[,c('uid','common','known_alive','followup_FI','followup_frail','FI6','fi_complete')],fit=ww$fit,probability=ww$p,retained_index=ww$ix,weight=ww$w,bootstrap=boot,bootstrap_seed=cohort_seed),file.path(out,paste0('IPW_',coh,'_audit.rds')))
 cat('IPW COMPLETE',coh,'\n');flush.console()
}
